import { Excalidraw } from "../index";

import { API } from "./helpers/api";
import { Pointer, UI } from "./helpers/ui";
import { render } from "./test-utils";

const mouse = new Pointer("mouse");

it("erases only unlocked arrows crossed by a fast swipe", async () => {
  await render(<Excalidraw />);
  API.setAppState({ width: 1000, height: 1000 });

  const arrowProps = {
    type: "arrow" as const,
    x: 100,
    y: 100,
    width: 200,
    height: 0,
    points: [pointFrom(0, 0), pointFrom(200, 0)],
    roughness: 0,
  };
  const arrow = API.createElement(arrowProps);
  const lockedArrow = API.createElement({ ...arrowProps, y: 200, locked: true });
  const untouchedArrow = API.createElement({ ...arrowProps, x: 300 });
  API.setElements([arrow, lockedArrow, untouchedArrow]);
  UI.clickTool("eraser");

  mouse.downAt(200, 50);
  mouse.moveTo(200, 250);
  mouse.up();

  expect(API.getElement(arrow).isDeleted).toBe(true);
  expect(API.getElement(lockedArrow).isDeleted).toBe(false);
  expect(API.getElement(untouchedArrow).isDeleted).toBe(false);
});
